import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-C11vx5L5.js";var i=JSON.parse(`{"path":"/english/vocabulary/school-education/talent-and-reputation/","title":"CH5.3 才智、声誉与治学 | 英语","lang":"zh-CN","frontmatter":{"title":"CH5.3 才智、声誉与治学","createTime":"2026-11-20T11:00:00.000Z","permalink":"/english/vocabulary/school-education/talent-and-reputation/"},"readingTime":{"minutes":34.76,"words":10428},"git":{"createdTime":1795161551000},"filePathRelative":"english/vocabulary/school-education/3.talent-and-reputation.md","headers":[],"bulletin":false}`),a={name:`3.talent-and-reputation.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="vocab-card"><h2 id="indulge" tabindex="-1"><a class="header-anchor" href="#indulge"><span>Indulge</span></a></h2><p class="vc-meta"><strong>/ɪnˈdʌldʒ/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>纵容、放任；满足（欲望）；沉溺于</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>indulge a child</td><td>纵容孩子</td></tr><tr><td>indulge in sth</td><td>沉溺于……</td></tr><tr><td>indulge oneself</td><td>放纵自己</td></tr><tr><td>an indulgent parent</td><td>溺爱孩子的家长</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The survey suggests that children whose parents indulge them are less able to manage money as adults.</p><blockquote><p>该调查表明，被父母纵容的孩子成年后理财能力更差。</p></blockquote><p><strong>Writing Task 2</strong> Parents who indulge every demand may believe they are showing love, but they are removing the very difficulties that build character.</p><blockquote><p>有求必应的父母或许自认在表达爱，实则移除了塑造品格的那些困难。</p></blockquote><p><strong>Speaking</strong> I indulged in a two-hour nap instead of revising, and I&#39;ve regretted it all week.</p><blockquote><p>我没复习，放纵自己睡了两小时，结果后悔了一整周。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>spoil</td><td>宠坏</td><td>强调结果：惯出坏毛病</td></tr><tr><td>pamper</td><td>娇养</td><td>强调照顾得过分周到</td></tr><tr><td>gratify</td><td>使满足</td><td>书面，指满足欲望本身</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> in-（朝向）+ dulg（拉丁语 <em>dulgere</em>，宽容）</li><li><strong>Family:</strong> indulgence 纵容 / indulgent 纵容的 / self-indulgent 自我放纵的</li><li><strong>Memory Tip:</strong> 前缀 in- 表&quot;朝向&quot;，词根 dulg 是&quot;宽容&quot;：一味顺着对方的意愿，就是纵容。同族形容词 indulgent 常修饰父母。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>搭配介词 in：indulge <strong>in</strong> desserts ✔，不说 <s>indulge on</s> ✘。</li><li>及物用法是 indulge sb / oneself，不是 <s>indulge to sb</s> ✘。</li><li>名词 indulgence，拼写有 dg，不是 <s>induljence</s>。</li></ul></div><div class="vocab-card"><h2 id="spoil" tabindex="-1"><a class="header-anchor" href="#spoil"><span>Spoil</span></a></h2><p class="vc-meta"><strong>/spɔɪl/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>宠坏、惯坏；破坏、毁掉；使（食物）变质</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>spoil a child</td><td>宠坏孩子</td></tr><tr><td>spoil the view</td><td>破坏景致</td></tr><tr><td>spoil the surprise</td><td>破坏惊喜</td></tr><tr><td>go off / spoil</td><td>变质</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> Teachers reported that pupils who were never told &quot;no&quot; at home were more likely to spoil group work for others.</p><blockquote><p>教师反映，在家里从未被拒绝过的学生，更容易破坏别人的小组作业。</p></blockquote><p><strong>Writing Task 2</strong> Giving a child everything he asks for does not express love; it spoils him and leaves him unable to tolerate frustration.</p><blockquote><p>孩子要什么就给什么并不是爱，而是把他宠坏，让他无法忍受挫折。</p></blockquote><p><strong>Speaking</strong> I spoiled the ending for myself by reading the last chapter first.</p><blockquote><p>我先读了最后一章，把结局给自己剧透了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>pamper</td><td>娇养</td><td>强调过度照顾，未必有坏结果</td></tr><tr><td>ruin</td><td>毁掉</td><td>语气更重，后果更彻底</td></tr><tr><td>damage</td><td>损害</td><td>可用于具体或抽象，程度较轻</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁语 <em>spoliare</em>（剥去、掠夺）→ 由&quot;剥夺&quot;转&quot;损坏&quot;</li><li><strong>Family:</strong> spoilt / spoiled 被宠坏的 / spoils 战利品 / despoil 掠夺</li><li><strong>Memory Tip:</strong> spoil 一词三义都从&quot;剥掉好东西&quot;来：剥掉孩子的韧性＝宠坏，剥掉景致＝破坏，剥掉食物的新鲜＝变质。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>过去式 spoiled / spoilt 均可，英式偏好 spoilt，但要全文统一。</li><li>&quot;宠坏&quot;是及物动词：<s>The child spoils.</s> ✘ → The child is spoiled ✔。</li><li>与 <strong>spill</strong>（洒出）拼写相近，注意 spo- 与 spi-。</li></ul></div><div class="vocab-card"><h2 id="abuse" tabindex="-1"><a class="header-anchor" href="#abuse"><span>Abuse</span></a></h2><p class="vc-meta"><strong>/əˈbjuːz/</strong> verb · <strong>/əˈbjuːs/</strong> noun · 动词／名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>滥用（权力、药物）；虐待；辱骂</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>abuse of power</td><td>滥用权力</td></tr><tr><td>drug / substance abuse</td><td>药物滥用</td></tr><tr><td>child abuse</td><td>虐待儿童</td></tr><tr><td>verbal abuse</td><td>言语辱骂</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> Cases of verbal abuse against teachers rose by a third over the five-year period.</p><blockquote><p>五年间，针对教师的言语辱骂事件上升了三分之一。</p></blockquote><p><strong>Writing Task 2</strong> Any system that lets administrators abuse their authority without review will eventually destroy the trust it depends on.</p><blockquote><p>任何让管理者可以在缺乏监督下滥用职权的制度，最终都会摧毁它所依赖的信任。</p></blockquote><p><strong>Speaking</strong> He abused my trust once, and I never lent him anything again.</p><blockquote><p>他辜负过我的信任一次，我就再没借给他任何东西。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>misuse</td><td>误用</td><td>多指无意的错误使用，恶意较轻</td></tr><tr><td>mistreat</td><td>虐待</td><td>只对应&quot;虐待&quot;义</td></tr><tr><td>exploit</td><td>利用</td><td>强调为己利而榨取</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> ab-（偏离）+ us（拉丁语 <em>uti</em>，使用）→ 偏离正当地使用</li><li><strong>Family:</strong> use 使用 / misuse 误用 / usage 用法 / disuse 废弃</li><li><strong>Memory Tip:</strong> 动词读 /z/ 结尾，名词读 /s/ 结尾——同一拼写两种读音，靠词性分辨。同类还有 house（名 /s/，动 /z/）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>词性辨音：to abuse /əˈbjuːz/；the abuse /əˈbjuːs/。</li><li>不说 <s>abuse of children of</s> ✘；正确是 abuse of children 或 child abuse。</li><li>拼写 a-buse，不是 <s>abbuse</s>。</li></ul></div><div class="vocab-card"><h2 id="intelligent" tabindex="-1"><a class="header-anchor" href="#intelligent"><span>Intelligent</span></a></h2><p class="vc-meta"><strong>/ɪnˈtelɪdʒənt/</strong> · adjective · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>聪明的、有智慧的；智能的（machine）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a highly intelligent student</td><td>非常聪明的学生</td></tr><tr><td>intelligent conversation</td><td>有见地的交谈</td></tr><tr><td>intelligent design</td><td>智能设计</td></tr><tr><td>emotionally intelligent</td><td>情商高的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph compares scores on a standard intelligence test across three age groups.</p><blockquote><p>该图比较了三个年龄组在标准智力测验中的得分。</p></blockquote><p><strong>Writing Task 2</strong> Being intelligent is not the same as being wise: intelligence solves problems, wisdom decides which problems matter.</p><blockquote><p>聪明不等于明智：智力解决问题，智慧决定哪些问题值得解决。</p></blockquote><p><strong>Speaking</strong> She&#39;s the most intelligent person I know, and also the worst at explaining anything.</p><blockquote><p>她是我认识的最聪明的人，也是最不会解释事情的人。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>clever</td><td>机灵的</td><td>偏反应快、会想办法，口语</td></tr><tr><td>smart</td><td>聪明的</td><td>美式口语，也指&quot;精明&quot;</td></tr><tr><td>intellectual</td><td>智力的</td><td>形容词多指学术、思辨层面</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> inter-（之间）+ leg（拉丁语 <em>legere</em>，挑选、读）→ 能在事物之间看出关联</li><li><strong>Family:</strong> intelligence 智力；情报 / intelligible 可理解的 / intellect 才智</li><li><strong>Memory Tip:</strong> leg＝挑选、读。intelligent 是&quot;能在众多信息里挑出关联&quot;；intelligence 还兼指&quot;情报&quot;，因为情报也是挑出来的信息。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>名词是 intelligence，不是 <s>intelligency</s>。</li><li>说人聪明用 intelligent / clever，不用 <s>intellectual</s>（后者多指&quot;从事脑力/学术的&quot;）。</li><li>重音在第二音节：/ɪnˈtelɪdʒənt/。</li></ul></div><div class="vocab-card"><h2 id="clever" tabindex="-1"><a class="header-anchor" href="#clever"><span>Clever</span></a></h2><p class="vc-meta"><strong>/ˈklevə(r)/</strong> · adjective · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>机灵的、巧妙的；手巧的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a clever idea</td><td>巧妙的主意</td></tr><tr><td>clever with one&#39;s hands</td><td>手很巧</td></tr><tr><td>too clever by half</td><td>聪明过头</td></tr><tr><td>a clever trick</td><td>巧妙的把戏</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The most cleverly designed exhibit was also the one children spent least time at.</p><blockquote><p>设计最巧妙的展品，恰恰是孩子们停留时间最短的那件。</p></blockquote><p><strong>Writing Task 2</strong> Clever students often pass exams on little work, which is precisely why they fail when the material becomes difficult.</p><blockquote><p>机灵的学生常能少用功就通过考试，这恰恰是他们在内容变难时失败的原因。</p></blockquote><p><strong>Speaking</strong> That was a clever way to avoid answering — I&#39;ll have to remember it.</p><blockquote><p>那是个回避回答的巧妙办法，我得记下来。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>smart</td><td>聪明的</td><td>更口语，也可指衣着整洁考究</td></tr><tr><td>bright</td><td>聪颖的</td><td>多形容孩子、学生，语气亲切</td></tr><tr><td>shrewd</td><td>精明的</td><td>常带算计意味，略含贬义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 中古英语 <em>cliver</em>，本义&quot;手爪灵活&quot;</li><li><strong>Family:</strong> cleverly 巧妙地 / cleverness 机灵 / clever-clogs（英式口语）自以为聪明的人</li><li><strong>Memory Tip:</strong> 由&quot;手巧&quot;扩到&quot;脑快&quot;。所以 clever with one&#39;s hands 保留了最古老的意思。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>比较级 cleverer，最高级 cleverest（也可用 more clever，但少见）。</li><li>形容人聪明用 clever，形容事物&quot;巧妙&quot;也用 clever：a clever plan ✔。</li><li>拼写 -ever，不是 <s>cleaver</s>（那是菜刀）。</li></ul></div><div class="vocab-card"><h2 id="smart" tabindex="-1"><a class="header-anchor" href="#smart"><span>Smart</span></a></h2><p class="vc-meta"><strong>/smɑːt/</strong> · adjective · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>聪明的、精明的；整洁漂亮的；（设备）智能的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a smart answer</td><td>机智的回答</td></tr><tr><td>smart casual</td><td>商务休闲装</td></tr><tr><td>smart technology</td><td>智能技术</td></tr><tr><td>look smart</td><td>显得精神、体面</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> Smart whiteboards were installed in 40 per cent of classrooms by 2022.</p><blockquote><p>到 2022 年，40% 的教室安装了智能白板。</p></blockquote><p><strong>Writing Task 2</strong> A smart student who never has to work hard at school may collapse at the first genuinely difficult task.</p><blockquote><p>在学校从不需要努力的精明学生，可能在一项真正困难的任务面前一败涂地。</p></blockquote><p><strong>Speaking</strong> I wore a smart jacket to the interview and immediately felt overdressed.</p><blockquote><p>我穿了件体面的外套去面试，立刻觉得自己穿过头了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>clever</td><td>机灵的</td><td>英式更常用，偏反应快</td></tr><tr><td>intelligent</td><td>有智慧的</td><td>更正式，偏能力层面</td></tr><tr><td>stylish</td><td>时髦的</td><td>只对应&quot;漂亮&quot;义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>smeortan</em>（刺痛）→ 由&quot;锐利&quot;引申为&quot;机敏&quot;</li><li><strong>Family:</strong> smartly 利落地 / smartness 整洁；机敏 / smartphone 智能手机</li><li><strong>Memory Tip:</strong> 原义&quot;刺痛&quot;，如 a smarting wound。刺痛是&quot;锐利&quot;的，锐利就转成了&quot;机敏&quot;和&quot;利落体面&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>英式里 smart 也指&quot;衣着讲究&quot;，美式多用它指&quot;聪明&quot;，读英美文章时注意语境。</li><li>不用于学术正式写作中的&quot;聪明&quot;（偏口语），正式场合用 intelligent。</li><li>比较级 smarter，不写 <s>more smart</s>。</li></ul></div><div class="vocab-card"><h2 id="all-round" tabindex="-1"><a class="header-anchor" href="#all-round"><span>All-round</span></a></h2><p class="vc-meta"><strong>/ˌɔːl ˈraʊnd/</strong> · adjective · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>全面的、多才多艺的；全方位的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>an all-round education</td><td>全面教育</td></tr><tr><td>an all-round student</td><td>全面发展的学生</td></tr><tr><td>all-round development</td><td>全面发展</td></tr><tr><td>an all-round improvement</td><td>全面改善</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The school&#39;s all-round performance improved in every category except attendance.</p><blockquote><p>除出勤外，学校在各方面表现均有提升。</p></blockquote><p><strong>Writing Task 2</strong> An all-round education should include music and sport, not only subjects that are tested.</p><blockquote><p>全面教育应包含音乐与体育，而不只是被考核的科目。</p></blockquote><p><strong>Speaking</strong> He&#39;s an all-round sportsman — decent at five sports, brilliant at none.</p><blockquote><p>他是个全能型运动员，五项都还行，没有一项特别出色。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>well-rounded</td><td>全面发展的</td><td>多形容人的素养均衡</td></tr><tr><td>comprehensive</td><td>综合的</td><td>多形容体系、方案涵盖面广</td></tr><tr><td>versatile</td><td>多才多艺的</td><td>强调能胜任多种角色</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>构成:</strong> all（全部）+ round（一圈）→ 各个方面都绕到了</li><li><strong>Family:</strong> all-rounder 全能选手 / round 圆形的；一轮 / around 周围</li><li><strong>Memory Tip:</strong> round 是&quot;一圈&quot;：把一圈都走遍，就是&quot;全面&quot;。all-rounder 指体育或职场上的全能型人物。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>连字符不可省：an all-round education ✔，<s>an all round education</s> ✘（易读成&quot;全部圆形&quot;）。</li><li>美式也说 all-around，但考试作文统一用 all-round。</li><li>只作定语，不作表语：<s>The education is all-round.</s> ✘ 宜说 It is a comprehensive education。</li></ul></div><div class="vocab-card"><h2 id="genius" tabindex="-1"><a class="header-anchor" href="#genius"><span>Genius</span></a></h2><p class="vc-meta"><strong>/ˈdʒiːniəs/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>天才；天才人物；非凡的才能</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a genius for ...</td><td>在……方面的天赋</td></tr><tr><td>a mathematical genius</td><td>数学天才</td></tr><tr><td>the genius of ...</td><td>……的精妙之处</td></tr><tr><td>a stroke of genius</td><td>神来之笔</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> Only a small fraction of the population is classified as genius by conventional tests.</p><blockquote><p>按常规测验，只有极少数人被归为天才。</p></blockquote><p><strong>Writing Task 2</strong> Calling a child a genius too early can be as damaging as calling him stupid, because both labels replace effort with identity.</p><blockquote><p>过早称孩子为天才，与骂他愚笨一样有害，因为两种标签都用&quot;身份&quot;替代了&quot;努力&quot;。</p></blockquote><p><strong>Speaking</strong> I have a genius for remembering faces and a complete inability to remember names.</p><blockquote><p>我记脸特别有天赋，记名字则完全不行。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>prodigy</td><td>神童</td><td>特指年少即显非凡才能者</td></tr><tr><td>talent</td><td>天赋</td><td>程度低于 genius，更常见</td></tr><tr><td>mastermind</td><td>幕后主脑</td><td>强调策划能力，可含贬义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁语 <em>genius</em>，指人出生时附体的守护神 → &quot;与生俱来的禀赋&quot;</li><li><strong>Family:</strong> genial 友善的 / ingenious 巧妙的 / congenital 先天的</li><li><strong>Memory Tip:</strong> genius 原指&quot;守护神&quot;，一个人的守护神决定了他的天赋。 ingenious（巧妙的）不要与 ingenuous（天真的）混。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：He is a genius ✔ / two geniuses ✔；<s>He has genius of maths</s> ✘。</li><li>说&quot;某方面的天赋&quot;用 a genius <strong>for</strong> sth。</li><li>重音在首音节：<strong>GE</strong>-nius，不是 <s>ge-NI-us</s>。</li></ul></div><div class="vocab-card"><h2 id="elite" tabindex="-1"><a class="header-anchor" href="#elite"><span>Elite</span></a></h2><p class="vc-meta"><strong>/eɪˈliːt/</strong> · noun / adjective · 名词／形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>精英、上层集团；精英的、精锐的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the ruling elite</td><td>统治精英</td></tr><tr><td>an elite university</td><td>精英大学</td></tr><tr><td>a member of the elite</td><td>精英阶层的一员</td></tr><tr><td>elite athletes</td><td>顶尖运动员</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows that graduates of elite universities earn roughly twice as much as other graduates.</p><blockquote><p>该图显示，精英大学的毕业生收入约为其他毕业生的两倍。</p></blockquote><p><strong>Writing Task 2</strong> When a handful of elite schools absorb the best teachers, the rest of the system inevitably declines.</p><blockquote><p>当少数精英学校吸走最好的教师，体系中的其余部分必然衰败。</p></blockquote><p><strong>Speaking</strong> She trained with the national elite for a year and decided she preferred ordinary life.</p><blockquote><p>她随国家队精英训练了一年，然后发现自己更喜欢普通生活。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>cream</td><td>精华</td><td>口语，the cream of 表&quot;最优秀的一批&quot;</td></tr><tr><td>upper crust</td><td>上层社会</td><td>口语，带调侃意味</td></tr><tr><td>select</td><td>精选的</td><td>强调经过筛选，不指阶层</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 法语 <em>élite</em>，源自拉丁语 <em>eligere</em>（挑选出）</li><li><strong>Family:</strong> elitist 精英主义者 / elitism 精英主义 / elect 选举（同源）</li><li><strong>Memory Tip:</strong> 与 elect 同源——&quot;被挑出来的&quot;。所以 elite 天然含&quot;少数、被筛选&quot;的意思，写作中常与 the 连用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>作名词时通常带 the：the elite ✔；指群体中一员用 a member of the elite。</li><li>重音在第二音节：/eɪˈliːt/，不是 <s>/ˈiːlaɪt/</s>。</li><li>拼写 e-lite，不是 <s>eliete</s>。</li></ul></div><div class="vocab-card"><h2 id="idiot" tabindex="-1"><a class="header-anchor" href="#idiot"><span>Idiot</span></a></h2><p class="vc-meta"><strong>/ˈɪdiət/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>白痴、傻瓜（贬义，慎用）；旧义&quot;智力严重障碍者&quot;</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>feel like an idiot</td><td>觉得自己像个傻瓜</td></tr><tr><td>a complete idiot</td><td>十足的傻瓜</td></tr><tr><td>idiot proof</td><td>傻瓜式的、极简易的</td></tr><tr><td>call sb an idiot</td><td>骂某人蠢</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The instructions were rewritten to be almost idiot-proof after repeated complaints.</p><blockquote><p>在多次投诉后，说明被改写成了几乎傻瓜式的操作。</p></blockquote><p><strong>Writing Task 2</strong> Labelling a struggling pupil an idiot is the surest way to make the label come true.</p><blockquote><p>把一个学得吃力的学生叫作白痴，是让这个标签成真的最可靠办法。</p></blockquote><p><strong>Speaking</strong> I felt like an idiot standing in the wrong queue for twenty minutes.</p><blockquote><p>我在错误的队伍里站了二十分钟，觉得自己像个傻瓜。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>fool</td><td>傻瓜</td><td>语气较轻，常用于自嘲</td></tr><tr><td>moron</td><td>蠢货</td><td>更粗鲁，避免书面使用</td></tr><tr><td>novice</td><td>新手</td><td>中性，只指经验不足</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊语 <em>idiōtēs</em>（平民、非专业人士）→ 由&quot;外行&quot;贬为&quot;愚人&quot;</li><li><strong>Family:</strong> idiocy 愚蠢 / idiotic 愚蠢的 / idiom 习语（同源，指&quot;特有的表达&quot;）</li><li><strong>Memory Tip:</strong> 原义只是&quot;普通人、外行&quot;。idiom（习语）同源，都是&quot;某一群体特有的&quot;。所以 idiot 的贬义是后来加的。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>属侮辱性词汇，正式写作与考试中避免用来指人。</li><li>拼写 -iot，不是 <s>ideot</s>；发音首音节 /ɪ/，不是 /aɪ/。</li><li>形容词是 idiotic /ˌɪdiˈɒtɪk/，重音后移。</li></ul></div><div class="vocab-card"><h2 id="wisdom" tabindex="-1"><a class="header-anchor" href="#wisdom"><span>Wisdom</span></a></h2><p class="vc-meta"><strong>/ˈwɪzdəm/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>智慧；明智；（前人的）经验之谈</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>conventional wisdom</td><td>通行看法</td></tr><tr><td>words of wisdom</td><td>至理名言</td></tr><tr><td>with the wisdom of hindsight</td><td>事后聪明地</td></tr><tr><td>practical wisdom</td><td>实践智慧</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The report questions the conventional wisdom that smaller classes always raise attainment.</p><blockquote><p>该报告质疑了&quot;班额越小成绩越好&quot;这一通行看法。</p></blockquote><p><strong>Writing Task 2</strong> Universities should teach wisdom as well as knowledge, yet no examination can measure patience, judgement or humility.</p><blockquote><p>大学应既教知识也教智慧，但没有考试能衡量耐心、判断力与谦逊。</p></blockquote><p><strong>Speaking</strong> My grandmother&#39;s advice sounded like clichés until I was thirty, and then it sounded like wisdom.</p><blockquote><p>我祖母的劝告在三十岁前听着像陈词滥调，之后就像至理名言了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>insight</td><td>洞察力</td><td>强调看透本质的能力</td></tr><tr><td>judgement</td><td>判断力</td><td>强调做决定的能力</td></tr><tr><td>knowledge</td><td>知识</td><td>只指所知，不含&quot;善用&quot;义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> wise（明智的）+ -dom（抽象名词后缀，表状态）</li><li><strong>Family:</strong> wise 明智的 / wisdom tooth 智齿 / kingdom 王国 / freedom 自由</li><li><strong>Memory Tip:</strong> -dom 是&quot;状态/领域&quot;后缀：wise＋dom＝明智的状态，king＋dom＝国王的领域，free＋dom＝自由的状态。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：<s>wisdoms</s> ✘；要量化说 a piece of wisdom。</li><li>&quot;智齿&quot;是 wisdom tooth，不是 <s>wisdom teeth</s>（单指一颗时）。</li><li>与 <strong>intelligence</strong> 分工：wisdom 含价值判断，intelligence 只是能力。</li></ul></div><div class="vocab-card"><h2 id="wit" tabindex="-1"><a class="header-anchor" href="#wit"><span>Wit</span></a></h2><p class="vc-meta"><strong>/wɪt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>机智、风趣；才思；（复数）智力、头脑</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a quick wit</td><td>反应机敏</td></tr><tr><td>dry wit</td><td>冷面幽默</td></tr><tr><td>at one&#39;s wits&#39; end</td><td>一筹莫展</td></tr><tr><td>keep one&#39;s wits about one</td><td>保持清醒</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The lecturer&#39;s wit kept a two-hour session from becoming a test of endurance.</p><blockquote><p>讲师的机智让两小时的课没有变成耐力考验。</p></blockquote><p><strong>Writing Task 2</strong> Wit is often mistaken for intelligence, yet it depends more on timing than on depth of thought.</p><blockquote><p>机智常被误认为智慧，其实它更依赖时机而非思想深度。</p></blockquote><p><strong>Speaking</strong> I was at my wits&#39; end trying to explain fractions to my nephew.</p><blockquote><p>我给侄子讲分数，讲到一筹莫展。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>humour</td><td>幽默</td><td>泛指引人发笑的特质</td></tr><tr><td>cleverness</td><td>机灵</td><td>只指聪明，不含风趣</td></tr><tr><td>repartee</td><td>妙语</td><td>特指对答如流的机锋</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>witt</em>（心智、知晓），与 wit（知道）同源</li><li><strong>Family:</strong> witty 机智的 / witness 目击者（&quot;知情者&quot;）/ outwit 智取</li><li><strong>Memory Tip:</strong> wit 本义是&quot;知道、心智&quot;，复数 wits 就是&quot;头脑&quot;。所以 at one&#39;s wits&#39; end 是&quot;头脑用尽&quot;，注意撇号在 s 之后。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>短语拼写：at one&#39;s wits&#39; end（wits 为复数所有格），常被误写成 <s>wit&#39;s end</s>。</li><li>不可数表&quot;风趣&quot;，复数 wits 表&quot;头脑&quot;，两者意义不同。</li><li>形容词 witty 双写 t：wit-ty。</li></ul></div><div class="vocab-card"><h2 id="aptitude" tabindex="-1"><a class="header-anchor" href="#aptitude"><span>Aptitude</span></a></h2><p class="vc-meta"><strong>/ˈæptɪtjuːd/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>天资、性向；（学习某事物的）接受能力</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>an aptitude for ...</td><td>对……的天赋</td></tr><tr><td>aptitude test</td><td>能力倾向测验</td></tr><tr><td>show an aptitude for music</td><td>显露音乐天赋</td></tr><tr><td>natural aptitude</td><td>天生的禀赋</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> Candidates were ranked by aptitude test scores rather than by school grades.</p><blockquote><p>候选人按能力倾向测验分数而非学校成绩排序。</p></blockquote><p><strong>Writing Task 2</strong> Entrance exams measure aptitude at a single moment, which is why they miss students who develop late.</p><blockquote><p>入学考试只测某一时刻的能力倾向，因此会漏掉晚熟的学生。</p></blockquote><p><strong>Speaking</strong> I showed no aptitude for maths but a suspicious amount of aptitude for arguing.</p><blockquote><p>我对数学毫无天赋，但对争论的天赋却高得可疑。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>talent</td><td>才能</td><td>常指已显现的、可训练的能力</td></tr><tr><td>flair</td><td>天分</td><td>强调风格与灵气，口语化</td></tr><tr><td>inclination</td><td>倾向</td><td>只指喜好，不含能力</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> apt（适合的）+ -itude（状态）</li><li><strong>Family:</strong> apt 恰当的；易于……的 / aptly 恰当地 / attitude 态度（形近）</li><li><strong>Memory Tip:</strong> apt 是&quot;合适、贴合&quot;：aptitude 就是&quot;与某件事天生贴合&quot;。注意别和 attitude（态度）混，二者只差一个字母。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词用 for：an aptitude <strong>for</strong> languages ✔，不用 <s>aptitude of</s> ✘。</li><li>与 <strong>attitude</strong> 区分：aptitude 是能力，attitude 是态度。</li><li>重音在首音节：<strong>AP</strong>-titude。</li></ul></div><div class="vocab-card"><h2 id="capable" tabindex="-1"><a class="header-anchor" href="#capable"><span>Capable</span></a></h2><p class="vc-meta"><strong>/ˈkeɪpəbl/</strong> · adjective · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>有能力的、能干的；能够……的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>be capable of doing sth</td><td>有能力做某事</td></tr><tr><td>a capable teacher</td><td>能干的教师</td></tr><tr><td>highly capable</td><td>能力很强的</td></tr><tr><td>capable hands</td><td>可靠的人手里</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> By the end of the course, all participants were capable of conducting a simple experiment unsupervised.</p><blockquote><p>课程结束时，所有学员都能在无人监督下完成简单实验。</p></blockquote><p><strong>Writing Task 2</strong> Children are far more capable of independent judgement than adults usually assume.</p><blockquote><p>儿童独立判断的能力远超成年人的设想。</p></blockquote><p><strong>Speaking</strong> I&#39;m perfectly capable of cooking — I simply refuse to do it after nine o&#39;clock.</p><blockquote><p>我完全有能力做饭，只是九点以后我拒绝动手。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>able</td><td>能够的</td><td>只用于 be able to do，不作定语</td></tr><tr><td>competent</td><td>胜任的</td><td>强调达到合格标准</td></tr><tr><td>skilled</td><td>熟练的</td><td>强调经过训练的技术水平</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> cap（拉丁语 <em>capere</em>，抓住、容纳）+ -able → 能接得住的</li><li><strong>Family:</strong> capability 能力 / capacity 容量 / capture 捕获 / captive 被俘的</li><li><strong>Memory Tip:</strong> cap＝抓、容纳。capable 是&quot;接得住任务&quot;，capacity 是&quot;装得下多少&quot;，capture 是&quot;抓住&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>只能作定语或接 of：a capable student ✔ / be capable <strong>of</strong> doing ✔；<s>be capable to do</s> ✘。</li><li>able 不能作前置定语：<s>an able student</s> 其实可接受，但 <s>an able to</s> ✘；二者搭配不同。</li><li>拼写 -able，不是 <s>-ible</s>。</li></ul></div><div class="vocab-card"><h2 id="excellent" tabindex="-1"><a class="header-anchor" href="#excellent"><span>Excellent</span></a></h2><p class="vc-meta"><strong>/ˈeksələnt/</strong> · adjective · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>优秀的、极好的；卓越的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>excellent academic performance</td><td>优异的学业表现</td></tr><tr><td>an excellent opportunity</td><td>绝佳的机会</td></tr><tr><td>excellent at / in ...</td><td>在……方面出色</td></tr><tr><td>a reputation for excellence</td><td>卓越的声誉</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The proportion of pupils achieving excellent grades doubled between 2010 and 2020.</p><blockquote><p>2010 至 2020 年间，取得优异成绩的学生比例翻了一倍。</p></blockquote><p><strong>Writing Task 2</strong> Excellent teaching cannot compensate for overcrowded classrooms and exhausted staff.</p><blockquote><p>优秀的教学无法弥补拥挤的教室和疲惫的教师。</p></blockquote><p><strong>Speaking</strong> Her English is excellent, but she still says &quot;very good&quot; when she means &quot;excellent&quot;.</p><blockquote><p>她的英语极好，但想说&quot;极好&quot;时还是会说&quot;very good&quot;。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>outstanding</td><td>杰出的</td><td>强调远高于一般水平</td></tr><tr><td>superb</td><td>极好的</td><td>语气更强，偏口语与文学</td></tr><tr><td>first-rate</td><td>一流的</td><td>口语化，多形容服务、设施</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> ex-（出）+ cell（拉丁语 <em>cellere</em>，高耸）→ 高出众上</li><li><strong>Family:</strong> excellence 卓越 / excel 擅长、胜过 / excellently 出色地</li><li><strong>Memory Tip:</strong> cell＝高。excellent 是&quot;高出来的&quot;；excel 既是动词&quot;擅长&quot;，也是软件名 Excel——都取&quot;胜过&quot;之义。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不用比较级 <s>more excellent</s>，本身已是最高程度；要比较改用 better。</li><li>名词是 <strong>excellence</strong>，注意 -ence 不是 -ance。</li><li>拼写双 l：exce-ll-ent，不是 <s>excelent</s>。</li></ul></div><div class="vocab-card"><h2 id="outstanding" tabindex="-1"><a class="header-anchor" href="#outstanding"><span>Outstanding</span></a></h2><p class="vc-meta"><strong>/aʊtˈstændɪŋ/</strong> · adjective · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>杰出的、突出的；未解决的、未支付的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>outstanding achievement</td><td>杰出成就</td></tr><tr><td>outstanding debts</td><td>未偿债务</td></tr><tr><td>outstanding issues</td><td>悬而未决的问题</td></tr><tr><td>an outstanding student</td><td>出类拔萃的学生</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> Outstanding results were concentrated in a small number of well-funded schools.</p><blockquote><p>优异的成绩集中在少数资金充足的学校。</p></blockquote><p><strong>Writing Task 2</strong> Rewarding only outstanding students may raise standards overall while widening the gap between the best and the rest.</p><blockquote><p>只奖励杰出学生或许能整体提高水平，却会拉大优者与其余人的差距。</p></blockquote><p><strong>Speaking</strong> Nothing about that essay was outstanding, but nothing was wrong with it either.</p><blockquote><p>那篇文章没有哪里出众，但也没有哪里出错。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>excellent</td><td>优秀的</td><td>程度略低于 outstanding</td></tr><tr><td>remarkable</td><td>显著的</td><td>强调值得注意，可褒可中</td></tr><tr><td>pending</td><td>待解决的</td><td>只对应&quot;未解决&quot;义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>构成:</strong> out（出）+ stand（站）+ -ing → 站出来、显眼</li><li><strong>Family:</strong> stand out 突出 / outstandingly 杰出地 / upstanding 正直的</li><li><strong>Memory Tip:</strong> 一个人从队伍里&quot;站出来（stand out）&quot;就是 outstanding。另一义&quot;未付的&quot;来自&quot;还立在那里没解决&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>重音在第二音节：/aʊtˈstændɪŋ/，不是 <s>/ˈaʊtstændɪŋ/</s>。</li><li>褒义与中性义要看搭配：outstanding debts 是&quot;未偿债务&quot;，不是&quot;杰出债务&quot;。</li><li>拼写 stand＋ing 保留双 d 前的 a：out-standing。</li></ul></div><div class="vocab-card"><h2 id="brilliant" tabindex="-1"><a class="header-anchor" href="#brilliant"><span>Brilliant</span></a></h2><p class="vc-meta"><strong>/ˈbrɪliənt/</strong> · adjective · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>才华横溢的、绝妙的；（光）明亮的、鲜艳的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a brilliant idea</td><td>绝妙的主意</td></tr><tr><td>brilliant at maths</td><td>数学极好</td></tr><tr><td>brilliant colours</td><td>鲜艳的色彩</td></tr><tr><td>a brilliant career</td><td>辉煌的事业</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart tracks the careers of brilliant graduates ten years after they left university.</p><blockquote><p>该图追踪了一批优秀毕业生离校十年后的职业发展。</p></blockquote><p><strong>Writing Task 2</strong> A brilliant mind without discipline achieves less than an ordinary mind with steady habits.</p><blockquote><p>才华横溢却缺乏自律的人，成就不如有稳定习惯的普通人。</p></blockquote><p><strong>Speaking</strong> She was brilliant at school and completely lost at university, because nobody had taught her how to fail.</p><blockquote><p>她在中学时极出色，到了大学却彻底迷失，因为没人教过她如何面对失败。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>dazzling</td><td>耀眼的</td><td>强调令人惊叹，也可字面指光</td></tr><tr><td>superb</td><td>极出色的</td><td>偏口语、评价性</td></tr><tr><td>vivid</td><td>鲜艳的</td><td>只对应颜色、记忆的鲜明义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 意大利语 <em>brillare</em>（闪耀）+ -ant → 闪闪发光的</li><li><strong>Family:</strong> brilliance 才华；光辉 / brilliantly 出色地 / brill（鱼名）鲽</li><li><strong>Memory Tip:</strong> 从&quot;发光&quot;到&quot;出彩&quot;：人一亮，就是才华；色一亮，就是鲜艳。brilliance 同时保留两种意思。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写双 l：bri-ll-iant，不是 <s>briliant</s>。</li><li>英式口语中 brilliant 也表&quot;太好了&quot;，学术写作中避免这种感叹用法。</li><li>名词是 brilliance（英式拼写），美式 brillance 罕见，统一用 -ance。</li></ul></div><div class="vocab-card"><h2 id="prestige" tabindex="-1"><a class="header-anchor" href="#prestige"><span>Prestige</span></a></h2><p class="vc-meta"><strong>/preˈstiːʒ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>威望、声誉；（因地位带来的）影响力</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>social prestige</td><td>社会声望</td></tr><tr><td>lose prestige</td><td>失去威望</td></tr><tr><td>a prestige university</td><td>名校、有声望的大学</td></tr><tr><td>for prestige rather than profit</td><td>为名不为利</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> Applications rose fastest at universities with the highest prestige, not the best teaching ratings.</p><blockquote><p>申请增长最快的是声望最高的大学，而非教学评价最好的大学。</p></blockquote><p><strong>Writing Task 2</strong> Vocational schools suffer less from poor teaching than from low prestige, which no reform can fix overnight.</p><blockquote><p>职业学校的问题与其说在教学质量，不如说在声望低，而这是任何改革都无法一夜改变的。</p></blockquote><p><strong>Speaking</strong> He took the job for the prestige, and quit within a year because the work was dull.</p><blockquote><p>他为名声接了那份工作，一年内就辞了，因为工作无聊。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>status</td><td>地位</td><td>强调社会阶层位置，较客观</td></tr><tr><td>standing</td><td>名望</td><td>强调他人眼中的评价，可高可低</td></tr><tr><td>reputation</td><td>声誉</td><td>指对某人品质的总体看法</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁语 <em>praestigium</em>（障眼法）→ 法语转义为&quot;名望带来的光环&quot;</li><li><strong>Family:</strong> prestigious 有声望的 / prestigiously 威风地</li><li><strong>Memory Tip:</strong> 原义竟是&quot;illusion（错觉）&quot;——名望本来就是别人眼中的一种光环。prestigious 是形容词，考试高频。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：<s>a prestige</s> ✘；作定语用 a prestige university。</li><li>重音在第二音节且 -tige 读 /tiːʒ/：<s>/ˈprestɪdʒ/</s> ✘。</li><li>形容词是 prestigious /preˈstɪdʒəs/，不是 <s>prestigeful</s>。</li></ul></div><div class="vocab-card"><h2 id="reputation" tabindex="-1"><a class="header-anchor" href="#reputation"><span>Reputation</span></a></h2><p class="vc-meta"><strong>/ˌrepjuˈteɪʃn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名声、声誉；名气</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>have a reputation for ...</td><td>以……著称</td></tr><tr><td>damage / ruin one&#39;s reputation</td><td>损害名声</td></tr><tr><td>build a reputation</td><td>建立声誉</td></tr><tr><td>a reputation as a strict teacher</td><td>以严格著称</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The college&#39;s reputation for engineering attracted students from twelve countries.</p><blockquote><p>该学院的工程学声誉吸引了来自十二个国家的学生。</p></blockquote><p><strong>Writing Task 2</strong> A school&#39;s reputation is built over decades and destroyed in a single scandal, which is why transparency matters more than marketing.</p><blockquote><p>学校的声誉需数十年建立，一场丑闻就能毁掉，因此透明比宣传更重要。</p></blockquote><p><strong>Speaking</strong> That restaurant has a reputation for terrible service, and it fully deserves it.</p><blockquote><p>那家餐厅以服务糟糕闻名，而且名副其实。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>name</td><td>名声</td><td>口语，如 make a name for oneself</td></tr><tr><td>image</td><td>形象</td><td>强调对外呈现的样子，可能是包装</td></tr><tr><td>standing</td><td>名望</td><td>强调相对位置，更客观</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> re-（反复）+ put（拉丁语 <em>putare</em>，思考、评价）+ -ation → 反复被评价的结果</li><li><strong>Family:</strong> repute 名声 / reputable 声誉良好的 / reputed 据称的 / reputation 声誉</li><li><strong>Memory Tip:</strong> put＝思考。别人反复&quot;想&quot;你，就形成了 reputation。reputable 是&quot;口碑好的&quot;，reputed 是&quot;据说的&quot;，注意区别。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数但不常用复数：a reputation ✔ / reputations 少见。</li><li>搭配 have a reputation <strong>for</strong> sth 或 <strong>as</strong> sth，不说 <s>reputation of</s> ✘（除非表所属）。</li><li>拼写 repu-tation，不是 <s>reputation</s> 中漏 t：<s>reputaion</s>。</li></ul></div><div class="vocab-card"><h2 id="eminent" tabindex="-1"><a class="header-anchor" href="#eminent"><span>Eminent</span></a></h2><p class="vc-meta"><strong>/ˈemɪnənt/</strong> · adjective · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>卓越的、著名的（多指学者、法官）；显著的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>an eminent scientist</td><td>著名科学家</td></tr><tr><td>eminent scholars</td><td>知名学者</td></tr><tr><td>of eminent standing</td><td>地位显赫的</td></tr><tr><td>eminent domain</td><td>（法律）征用权</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The lecture series featured six eminent economists from four countries.</p><blockquote><p>该系列讲座由来自四国的六位著名经济学家主讲。</p></blockquote><p><strong>Writing Task 2</strong> Eminent researchers are often poor teachers, yet universities promote them precisely because of their research.</p><blockquote><p>著名研究者往往并不擅长教学，而大学恰恰因研究成绩提拔他们。</p></blockquote><p><strong>Speaking</strong> An eminent professor once told me that half of his published work was wrong, and that he was proud of the half that wasn&#39;t.</p><blockquote><p>一位著名教授曾跟我说，他发表的东西一半是错的，他为没错的那一半感到自豪。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>distinguished</td><td>卓越的</td><td>强调成就受公认，语气温和</td></tr><tr><td>renowned</td><td>享有盛誉的</td><td>强调广为人知</td></tr><tr><td>prominent</td><td>显要的</td><td>强调地位突出、易被看见</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> e-（出）+ min（拉丁语 <em>minere</em>，突出）→ 凸出来</li><li><strong>Family:</strong> eminence 卓越 / imminent 迫近的（形近，勿混）/ prominent 突出的 / imminent 迫在眉睫的</li><li><strong>Memory Tip:</strong> min＝突出。eminent 是&quot;在人之上&quot;，imminent 是&quot;逼近到眼前&quot;，prominent 是&quot;往前突出&quot;——三者只差前缀。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>与 <strong>imminent</strong>（即将发生的）严格区分，拼写只差一个字母。</li><li>形容人多指年长、地位稳固者，形容年轻学者用 promising。</li><li>重音在首音节：<strong>EM</strong>-inent。</li></ul></div><div class="vocab-card"><h2 id="notorious" tabindex="-1"><a class="header-anchor" href="#notorious"><span>Notorious</span></a></h2><p class="vc-meta"><strong>/nəʊˈtɔːriəs/</strong> · adjective · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>臭名昭著的、声名狼藉的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>be notorious for ...</td><td>因……而臭名昭著</td></tr><tr><td>a notorious case</td><td>著名的恶性案件</td></tr><tr><td>notoriously difficult</td><td>出了名地难</td></tr><tr><td>a notorious liar</td><td>出了名的爱说谎</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The city&#39;s transport system is notorious for delays during the winter months.</p><blockquote><p>该市交通系统以冬季频繁延误而闻名。</p></blockquote><p><strong>Writing Task 2</strong> Multiple-choice tests are notorious for rewarding guesswork as much as knowledge.</p><blockquote><p>多项选择题出了名地既奖励知识，也奖励瞎猜。</p></blockquote><p><strong>Speaking</strong> This road is notorious for accidents, and yet people still overtake on the bend.</p><blockquote><p>这条路因事故频发而出名，可人们还是在弯道超车。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>infamous</td><td>声名狼藉的</td><td>语气更重，多指恶行</td></tr><tr><td>ill-famed</td><td>名声不好的</td><td>罕见，书面</td></tr><tr><td>famous</td><td>著名的</td><td>褒义，与 notorious 立场相反</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> not（拉丁语 <em>notus</em>，已知）+ -orious → 出了名地被知道</li><li><strong>Family:</strong> notoriety 恶名 / notably 显著地 / notice 注意 / notify 通知</li><li><strong>Memory Tip:</strong> 与 famous 结构相同，都是&quot;被知道&quot;，区别在评价方向：notorious 只用于坏事。同根的名词 notoriety 也是贬义。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>只能用于负面事物：<s>a notorious hero</s> ✘；褒义用 renowned / celebrated。</li><li>介词用 for：notorious <strong>for</strong> cheating ✔。</li><li>拼写 -orious，不是 <s>-ourous</s>。</li></ul></div><div class="vocab-card"><h2 id="esteem" tabindex="-1"><a class="header-anchor" href="#esteem"><span>Esteem</span></a></h2><p class="vc-meta"><strong>/ɪˈstiːm/</strong> · noun / verb · 名词／动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>尊重、敬重；评价、认为</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>hold sb in high esteem</td><td>高度尊重某人</td></tr><tr><td>self-esteem</td><td>自尊</td></tr><tr><td>a mark of esteem</td><td>敬意的表示</td></tr><tr><td>esteem sth highly</td><td>高度评价某物</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> Teachers reported that low self-esteem was the strongest predictor of dropout among boys.</p><blockquote><p>教师反映，自尊偏低是男生辍学最强的预测因素。</p></blockquote><p><strong>Writing Task 2</strong> A system that ranks children publicly may raise scores while quietly destroying the self-esteem of the majority.</p><blockquote><p>公开给孩子排名的制度或许能提高分数，却在悄悄摧毁多数人的自尊。</p></blockquote><p><strong>Speaking</strong> I hold my old Latin teacher in the highest esteem — she made a dead language feel alive.</p><blockquote><p>我最敬重从前的拉丁语老师，她让一门死语言活了起来。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>respect</td><td>尊重</td><td>更常用，可指对人也可对规则</td></tr><tr><td>regard</td><td>看重</td><td>常与 highly 连用表评价</td></tr><tr><td>admiration</td><td>钦佩</td><td>强调赞赏其品质或成就</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁语 <em>aestimare</em>（估价）→ 给人高的估价就是尊重</li><li><strong>Family:</strong> estimate 估计 / estimation 判断 / estimable 值得尊敬的</li><li><strong>Memory Tip:</strong> esteem 与 estimate 同源，都是&quot;估价&quot;。esteem 是给人&quot;高估价&quot;，所以 hold sb in high esteem＝把某人估得很高。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>固定搭配 hold sb in high esteem，介词是 in，不是 <s>hold sb with esteem</s> ✘。</li><li>self-esteem 有连字符，不是 <s>selfesteem</s>。</li><li>作动词较正式：I esteem him highly ✔，日常多用 respect。</li></ul></div><div class="vocab-card"><h2 id="respect" tabindex="-1"><a class="header-anchor" href="#respect"><span>Respect</span></a></h2><p class="vc-meta"><strong>/rɪˈspekt/</strong> · noun / verb · 名词／动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>尊重、敬意；方面；遵守（规则）；尊重（他人意愿）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>show respect for ...</td><td>对……表示尊重</td></tr><tr><td>with respect to ...</td><td>关于……</td></tr><tr><td>in this respect</td><td>在这方面</td></tr><tr><td>respect the rules</td><td>遵守规则</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> Discipline problems fell sharply once pupils felt their teachers respected them.</p><blockquote><p>一旦学生感到教师尊重自己，纪律问题便大幅下降。</p></blockquote><p><strong>Writing Task 2</strong> Students should respect their teachers, but respect that is demanded rather than earned is merely obedience.</p><blockquote><p>学生应当尊重老师，但被要求而非赢得的尊重，只是服从。</p></blockquote><p><strong>Speaking</strong> In that respect, my father and I are identical — we both apologize by fixing things instead of talking.</p><blockquote><p>在这方面我和父亲一模一样：我们都用修好一件东西来代替道歉。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>regard</td><td>尊重</td><td>更书面，常用 hold in regard</td></tr><tr><td>deference</td><td>顺从</td><td>强调对地位高者的礼让</td></tr><tr><td>admiration</td><td>钦佩</td><td>只指赞赏，不含&quot;遵守&quot;义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> re-（回）+ spect（拉丁语 <em>specere</em>，看）→ 回头看，即重视</li><li><strong>Family:</strong> respectful 恭敬的 / respective 各自的 / inspect 检查 / aspect 方面</li><li><strong>Memory Tip:</strong> spect＝看。respect 是&quot;再看一眼&quot;（重视），inspect 是&quot;往里看&quot;（检查），aspect 是&quot;看到的那一面&quot;（方面）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>形容词三分：respectful（恭敬的）、respectable（体面的）、respective（各自的），常被混用。</li><li>&quot;关于&quot;用 with respect <strong>to</strong>，不是 <s>in respect of</s> 之外混写成 <s>with respect of</s>。</li><li>作名词表&quot;方面&quot;时可数：in many respects ✔。</li></ul></div><div class="vocab-card"><h2 id="diligent" tabindex="-1"><a class="header-anchor" href="#diligent"><span>Diligent</span></a></h2><p class="vc-meta"><strong>/ˈdɪlɪdʒənt/</strong> · adjective · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>勤奋的、勤勉的；用心的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a diligent student</td><td>勤奋的学生</td></tr><tr><td>diligent in doing sth</td><td>勤于做某事</td></tr><tr><td>diligent research</td><td>细致的调查研究</td></tr><tr><td>hard-working and diligent</td><td>勤恳努力</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> Diligent students improved steadily, while those relying on talent plateaued after the first term.</p><blockquote><p>勤奋的学生稳步提高，而依赖天赋者在第一学期后便停滞不前。</p></blockquote><p><strong>Writing Task 2</strong> Talent is worthless without diligence, and diligence without curiosity rarely produces anything original.</p><blockquote><p>没有勤奋，天赋一文不值；没有好奇，勤奋也难有创见。</p></blockquote><p><strong>Speaking</strong> She was the most diligent person in our year — in bed by ten, up at five, every single day.</p><blockquote><p>她是我们年级最勤奋的人：十点睡、五点起，每天如此。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>hard-working</td><td>努力工作的</td><td>口语，最常用</td></tr><tr><td>industrious</td><td>勤劳的</td><td>书面，多形容群体或品性</td></tr><tr><td>studious</td><td>好学的</td><td>特指学习上用功</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> di-（分开）+ lig（拉丁语 <em>legere</em>，挑选）→ 认真挑选、不马虎</li><li><strong>Family:</strong> diligence 勤勉 / diligently 勤勉地 / diligent 勤奋的</li><li><strong>Memory Tip:</strong> 名词 diligence 现在也指&quot;尽职调查&quot;（due diligence），因为本义就是&quot;认真细致&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>说&quot;勤于做某事&quot;用 diligent <strong>in</strong> doing，不用 <s>diligent to do</s> ✘。</li><li>拼写 -gent，不是 <s>-gant</s>（注意与 elegant 的 -gant 区分）。</li><li>名词 diligence，不是 <s>diligency</s>。</li></ul></div><div class="vocab-card"><h2 id="painstaking" tabindex="-1"><a class="header-anchor" href="#painstaking"><span>Painstaking</span></a></h2><p class="vc-meta"><strong>/ˈpeɪnzteɪkɪŋ/</strong> · adjective · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>极其仔细的、煞费苦心的；勤勉的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>painstaking research</td><td>一丝不苟的研究</td></tr><tr><td>painstaking attention to detail</td><td>对细节的极致关注</td></tr><tr><td>painstaking work</td><td>细致艰苦的工作</td></tr><tr><td>painstakingly accurate</td><td>精确到极致</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The data was collected through painstaking interviews with over three hundred families.</p><blockquote><p>这些数据是通过对三百多个家庭的细致访谈收集的。</p></blockquote><p><strong>Writing Task 2</strong> Good scholarship is painstaking rather than brilliant: it consists of checking what everyone else assumed.</p><blockquote><p>好的学术是细致苦干而非灵光一现：它做的就是核查所有人想当然的事。</p></blockquote><p><strong>Speaking</strong> Restoring that old map was painstaking work — six months with a magnifying glass.</p><blockquote><p>修复那张旧地图是极细致的工作，用放大镜干了六个月。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>meticulous</td><td>一丝不苟的</td><td>强调对细节的精确要求</td></tr><tr><td>thorough</td><td>彻底的</td><td>强调覆盖全面，不含&quot;费力&quot;义</td></tr><tr><td>laborious</td><td>费力的</td><td>强调过程艰苦，未必细致</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>构成:</strong> pains（辛苦）+ taking（花费）→ 肯下苦功的</li><li><strong>Family:</strong> take pains to do 费心去做 / painstakingly 极其仔细地</li><li><strong>Memory Tip:</strong> 字面是&quot;把 pain 都 take 下来&quot;，即肯吃这份苦。take pains 是固定短语：take great pains to be accurate。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>是形容词，不是副词：<s>He worked painstaking</s> ✘ → painstakingly。</li><li>拼写是两个词根合成，中间无连字符：painstaking，不写 <s>pain-staking</s>。</li><li>不表示&quot;痛苦的&quot;（那是 painful），只表&quot;极其用心&quot;。</li></ul></div><div class="vocab-card"><h2 id="skill" tabindex="-1"><a class="header-anchor" href="#skill"><span>Skill</span></a></h2><p class="vc-meta"><strong>/skɪl/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>技能、技巧；熟练程度</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>acquire / develop a skill</td><td>习得技能</td></tr><tr><td>communication skills</td><td>沟通能力</td></tr><tr><td>a high level of skill</td><td>高超的技艺</td></tr><tr><td>skill in doing sth</td><td>做某事的技巧</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> Employers ranked communication skills above academic qualifications in the survey.</p><blockquote><p>在调查中，雇主把沟通能力排在学历之上。</p></blockquote><p><strong>Writing Task 2</strong> Schools teach knowledge efficiently but neglect the practical skills that adults need every day.</p><blockquote><p>学校高效地传授知识，却忽视了成年人每天都要用的实用技能。</p></blockquote><p><strong>Speaking</strong> Cooking is a skill, not a talent — I learned it at thirty and I&#39;m still learning.</p><blockquote><p>做饭是技能而非天赋，我三十岁才学，现在还在学。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>expertise</td><td>专业专长</td><td>程度更高，含深厚专业知识</td></tr><tr><td>technique</td><td>技法</td><td>指具体操作方法，可数</td></tr><tr><td>competence</td><td>胜任能力</td><td>强调达到要求，偏评估语境</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古诺斯语 <em>skil</em>（辨别、知识）</li><li><strong>Family:</strong> skilled 熟练的 / skilful（英）/ skillful（美）熟练的 / unskilled 非技术的</li><li><strong>Memory Tip:</strong> skill 与 skilled 一起记：名词加 -ed 变&quot;有技能的&quot;。英式 skilful 单 l，美式 skillful 双 l。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a skill / many skills ✔；抽象&quot;熟练&quot;不可数：show great skill ✔。</li><li>说&quot;某方面的技能&quot;用 skills <strong>in</strong> sth，不用 <s>skills of doing</s>（较少）。</li><li>拼写单 l，不是 <s>skill</s> 加多余的 l 成 <s>skil</s>。</li></ul></div><div class="vocab-card"><h2 id="approach" tabindex="-1"><a class="header-anchor" href="#approach"><span>Approach</span></a></h2><p class="vc-meta"><strong>/əˈprəʊtʃ/</strong> · noun / verb · 名词／动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>方法、途径；接近、靠近；着手处理</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>an approach to ...</td><td>处理……的方法</td></tr><tr><td>adopt a new approach</td><td>采取新方法</td></tr><tr><td>approach a problem</td><td>着手处理问题</td></tr><tr><td>as exams approach</td><td>随着考试临近</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The school adopted a different approach to teaching reading, with measurable results within a year.</p><blockquote><p>该校对阅读教学采取了不同方法，一年内便有了可衡量的成效。</p></blockquote><p><strong>Writing Task 2</strong> A purely punitive approach to discipline addresses the symptom while leaving the cause untouched.</p><blockquote><p>纯粹以惩罚为主的管教方式只处理症状，未触及原因。</p></blockquote><p><strong>Speaking</strong> I&#39;ve tried every approach to memorising vocabulary, and none beats reading a lot.</p><blockquote><p>背单词的方法我全试过，没有一种比得上大量阅读。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>method</td><td>方法</td><td>更具体，指可复制的步骤</td></tr><tr><td>strategy</td><td>策略</td><td>强调长期规划与取舍</td></tr><tr><td>scheme</td><td>方案</td><td>常指官方或系统的安排</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> ap-（=ad，朝向）+ proach（拉丁语 <em>prope</em>，近）→ 走近</li><li><strong>Family:</strong> approachable 平易近人的 / reproach 责备（形近）/ approximate 大约的</li><li><strong>Memory Tip:</strong> prope＝近。approach 是&quot;走近&quot;，所以既能指&quot;接近某地/某人&quot;，也能指&quot;接近一个问题&quot;的着手方式。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>名词搭配是 an approach <strong>to</strong> sth，to 是介词，后接动名词：an approach to teaching ✔ / <s>approach to teach</s> ✘。</li><li>作动词及物：approach the problem ✔，不用 <s>approach to the problem</s> ✘。</li><li>拼写双 p：a-pp-roach，不是 <s>aprouch</s>。</li></ul></div><div class="vocab-card"><h2 id="scheme" tabindex="-1"><a class="header-anchor" href="#scheme"><span>Scheme</span></a></h2><p class="vc-meta"><strong>/skiːm/</strong> · noun / verb · 名词／动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>计划、方案（官方或系统性的）；阴谋；密谋</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a scholarship scheme</td><td>奖学金计划</td></tr><tr><td>a pension scheme</td><td>养老金方案</td></tr><tr><td>a scheme to do sth</td><td>做某事的计划</td></tr><tr><td>scheme against sb</td><td>密谋对付某人</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The government introduced a scheme offering free transport to students in rural areas.</p><blockquote><p>政府推出了一项为农村学生提供免费交通的计划。</p></blockquote><p><strong>Writing Task 2</strong> Voucher schemes often divert public money to private providers without improving results.</p><blockquote><p>教育券计划常把公共资金导向私营机构，却没能改善结果。</p></blockquote><p><strong>Speaking</strong> The bike scheme sounded great until I found out there were only three bikes.</p><blockquote><p>那项自行车计划听着不错，直到我发现只有三辆车。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>plan</td><td>计划</td><td>最通用，中性</td></tr><tr><td>programme</td><td>项目</td><td>多指一整套持续性安排</td></tr><tr><td>plot</td><td>阴谋</td><td>只对应&quot;密谋&quot;义，贬义更明确</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊语 <em>skhēma</em>（形状、安排）</li><li><strong>Family:</strong> schematic 示意的 / schema 图式 / schemer 阴谋家</li><li><strong>Memory Tip:</strong> 原义是&quot;形状、布局&quot;，所以 scheme 既指&quot;安排出来的方案&quot;，也指&quot;暗中布好的局&quot;。英式英语里 scheme 多为中性，美式常偏贬义。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>英美色彩：英式 a training scheme＝培训计划（中性）；美式 scheme 常指&quot;诡计&quot;，写作时注意读者。</li><li>可数：a scheme / several schemes ✔。</li><li>拼写 sch-，不是 <s>skeme</s>。</li></ul></div>`,28)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};